// WF-001 — Validate Request Schema
// Canonical envelope: contracts/models.py::RequestEnvelope
// N8N-005: pin the schema and reject unknown values for critical enums.
// N8N-009 / ARC-003: require an idempotency key for side-effecting intents.

const ALLOWED_INTENTS = [
  'text_recommendation',
  'audio_vibe_recommendation',
  'audio_identification',
  'feedback',
  'playlist_export',
  'auth_connection_sync',
];
const ALLOWED_LOCALES = ['en', 'he'];
const ALLOWED_DISCOVERY = ['safe', 'balanced', 'adventurous'];
// ARC-003 §4.1 — these intents cause an external or immutable side effect.
const IDEMPOTENT_INTENTS = ['feedback', 'playlist_export', 'auth_connection_sync'];
const SUPPORTED_API_VERSIONS = ['v1'];
const MAX_PROMPT_CHARS = 1000;

const out = [];
for (const item of $input.all()) {
  const raw = item.json || {};
  // The Webhook node nests the posted JSON under `body`; the manual test path
  // (Mock Flask Data) supplies the envelope directly. Accept both rather than
  // assuming one shape.
  const env = (raw.body && (raw.body.intent || raw.body.api_version)) ? raw.body : raw;
  const body = env.body || {};
  const identity = env.identity || {};

  const apiVersion = (env.api_version || 'v1').toString();
  if (!SUPPORTED_API_VERSIONS.includes(apiVersion)) {
    throw new Error('VALIDATION_ERROR: unsupported api_version "' + apiVersion + '"');
  }

  const intent = (env.intent || '').toString().trim().toLowerCase();
  if (!intent) {
    throw new Error('VALIDATION_ERROR: intent is required');
  }
  if (!ALLOWED_INTENTS.includes(intent)) {
    throw new Error('VALIDATION_ERROR: unknown intent "' + intent + '"');
  }

  const locale = (env.locale || 'en').toString().trim().toLowerCase();
  if (!ALLOWED_LOCALES.includes(locale)) {
    throw new Error('VALIDATION_ERROR: unsupported locale "' + locale + '"');
  }

  const ctx = body.recommendation_context || {};
  const discoveryMode = (ctx.discovery_mode || 'balanced').toString().trim().toLowerCase();
  if (!ALLOWED_DISCOVERY.includes(discoveryMode)) {
    throw new Error('VALIDATION_ERROR: unknown discovery_mode "' + discoveryMode + '"');
  }

  const message = (body.prompt || body.message || '').toString();
  if (message.length > MAX_PROMPT_CHARS) {
    throw new Error('VALIDATION_ERROR: prompt exceeds ' + MAX_PROMPT_CHARS + ' characters');
  }
  if (!message && intent === 'text_recommendation') {
    throw new Error('VALIDATION_ERROR: prompt is required for text_recommendation');
  }

  const idempotencyKey = (env.idempotency_key || '').toString().trim();
  if (IDEMPOTENT_INTENTS.includes(intent) && !idempotencyKey) {
    throw new Error('VALIDATION_ERROR: idempotency_key is required for intent "' + intent + '"');
  }

  // N8N-004: request_id is guaranteed present from here on. `Initialize
  // Execution metadata` already generated one when the client omitted it.
  const requestId = (
    env.request_id || raw.request_id || $execution.id
  ).toString();

  out.push({
    json: {
      apiVersion,
      requestId,
      intent,
      locale,
      discoveryMode,
      idempotencyKey: idempotencyKey || null,
      userId: identity.user_id || null,
      guestId: identity.guest_id || null,
      sessionId: identity.session_id || null,
      message,
      // The full validated envelope travels to the sub-workflow unchanged.
      envelope: env,
      valid: true,
    },
  });
}
return out;
